  /* ── 四月 ── */
  '2027-04-01': { f:'粉玫瑰', n:59, love:'坚持这件事，我只对花和你认真过。' },
  '2027-04-02': { f:'粉玫瑰', n:5, love:'你手凉，握花之前先搓一搓。' },
  '2027-04-03': { f:'红玫瑰', n:48, love:'我把买花写进了日程，排在所有事前面。' },
  '2027-04-04': { f:'黑心菊', n:91, love:'你吃饭了吗？这句话我一天想问三遍。' },
  '2027-04-05': { f:'虎皮百合', n:36, love:'我不在的时候，花替我值班。' },
  '2027-04-06': { f:'台湾百合', n:80, love:'每天一束，说难不难，说容易也不容易。' },
  '2027-04-07': { f:'非洲菊', n:25, love:'隔着一段路，我把花先送过去。' },
  '2027-04-08': { f:'向日葵', n:69, love:'数字不重要，重要的是每天都数。' },
  '2027-04-09': { f:'红玫瑰', n:15, love:'光从花瓣上滑下来，落在我手上，像你。' },
  '2027-04-10': { f:'芍药', n:33, love:'又长大一岁。我不祝你万事顺遂，我只祝你年年都有人这样给你买花。' },
  '2027-04-11': { f:'紫罗兰', n:3, love:'今天没什么特别的，就是有花。' },
  '2027-04-12': { f:'白玫瑰', n:48, love:'花香不响，却比什么都吵。' },
  '2027-04-13': { f:'木绣球', n:91, love:'花放在你桌上，占了半个屏幕的位置。值得。' },
  '2027-04-14': { f:'绣球', n:36, love:'今天的天气配这束花，刚刚好。' },
  '2027-04-15': { f:'牡丹', n:80, love:'下雪了。花在屋里，你在路上，我在等。' },
  '2027-04-16': { f:'芍药', n:25, love:'走之前替你把花挪到阴一点的地方。' },
  '2027-04-17': { f:'卡布奇诺玫瑰', n:69, love:'我把花放在你必经的地方。' },
  '2027-04-18': { f:'白玫瑰', n:15, love:'我离你有点远，花离你很近。' },
  '2027-04-19': { f:'粉玫瑰', n:58, love:'秋天的花贵一点，我还是买了。' },
  '2027-04-20': { f:'白玫瑰', n:3, love:'你的手很适合拿花。' },
  '2027-04-21': { f:'粉玫瑰', n:48, love:'我不喜欢热闹，只喜欢你在的那点安静。' },
  '2027-04-22': { f:'黑心菊', n:90, love:'你说话的时候，我在看你的手。' },
  '2027-04-23': { f:'虎皮百合', n:35, love:'愿你晚上睡个好觉，梦里没有工作。' },
  '2027-04-24': { f:'台湾百合', n:79, love:'雪落在窗台上，花落在光里，我落在想你里。' },
  '2027-04-25': { f:'非洲菊', n:24, love:'它开得不算完美，可它是今天的。' },
  '2027-04-26': { f:'向日葵', n:68, love:'我把话咽回去了，换成一束花。' },
  '2027-04-27': { f:'朱顶红', n:13, love:'一天一束，一年就是三百多束。' },
  '2027-04-28': { f:'玉兰', n:57, love:'一天一束，是我能想到最笨也最实的表达。' },
