  '2027-04-30': { f:'飞燕草', n:46, love:'老板说这种花不耐放，我说没关系，明天再来。' },

  /* ── 五月 ── */
  '2027-05-01': { f:'木绣球', n:90, love:'我把花递过去的时候，碰到了你的手指。' },
  '2027-05-02': { f:'绣球', n:35, love:'距离不算什么，花能到的地方，话也能到。' },
  '2027-05-03': { f:'牡丹', n:79, love:'叶子比花老实，一直在下面托着。' },
  '2027-05-04': { f:'芍药', n:24, love:'今天这束是第几束我不知道，反正不是最后一束。' },
  '2027-05-05': { f:'卡布奇诺玫瑰', n:68, love:'愿你偶尔想起我，就够了。' },
  '2027-05-06': { f:'香槟玫瑰', n:13, love:'我想和你过很多个普通的明天。' },
  '2027-05-07': { f:'粉玫瑰', n:57, love:'门开着的时候，风把花香送进去了。' },
