  '2027-05-09': { f:'红玫瑰', n:46, love:'花在窗台上等了一夜，就为了你起床时看见。' },
  '2027-05-10': { f:'黑心菊', n:89, love:'路灯亮起来的时候，我刚好走到花店。' },
  '2027-05-11': { f:'虎皮百合', n:34, love:'你的名字我写在花束的卡片背面了。' },
  '2027-05-12': { f:'台湾百合', n:78, love:'明年这个时候，花会更多。' },
  '2027-05-13': { f:'非洲菊', n:23, love:'回家的路上买了一束花，路就不算白走。' },
  '2027-05-14': { f:'向日葵', n:67, love:'春天来了。我把第一束春天给你。' },
  '2027-05-15': { f:'朱顶红', n:12, love:'字会写错，花不会。' },
  '2027-05-16': { f:'玉兰', n:56, love:'你不用每次都道谢，我本来就想送。' },
  '2027-05-17': { f:'紫罗兰', n:1, love:'我把花摆在你看得到的地方，剩下的交给它。' },
  '2027-05-18': { f:'飞燕草', n:45, love:'明年今日，我还会站在同一个花店。' },
  '2027-05-19': { f:'木绣球', n:89, love:'今天没下雨，花一路都很好。' },
  '2027-05-20': { f:'绣球', n:34, love:'愿你想起这束花的时候，是笑着的。' },
  '2027-05-21': { f:'牡丹', n:78, love:'下雨天买花很傻。可我本来就不太聪明。' },
  '2027-05-22': { f:'芍药', n:23, love:'你今天回不回？花在门口站了一天。' },
  '2027-05-23': { f:'卡布奇诺玫瑰', n:67, love:'我挑了很久，最后拿了最像你的那一束。' },
  '2027-05-24': { f:'香槟玫瑰', n:12, love:'下雪天不想出门。可花已经在路上了。' },
  '2027-05-25': { f:'粉玫瑰', n:56, love:'喜欢你这件事，我做得最久。' },
  '2027-05-26': { f:'白玫瑰', n:1, love:'我说不出想你，就说今天有花。' },
  '2027-05-27': { f:'红玫瑰', n:45, love:'等一个人不苦，苦的是不知道等到哪天。' },
  '2027-05-28': { f:'黑心菊', n:88, love:'累的话就先坐一会儿，花不急。' },
  '2027-05-29': { f:'虎皮百合', n:33, love:'愿你所有的疲惫都有人接住。' },
  '2027-05-30': { f:'台湾百合', n:77, love:'你走之后，屋里最响的是花香。' },
  '2027-05-31': { f:'非洲菊', n:22, love:'地铁很挤，只有花是站着的。' },

  /* ── 六月 ── */
  '2027-06-01': { f:'向日葵', n:66, love:'我不能每天都见到你，但花能。' },
  '2027-06-02': { f:'朱顶红', n:11, love:'花会谢，这件事不会。' },
  '2027-06-03': { f:'玉兰', n:55, love:'花店老板问送给谁，我说了你的名字。' },
  '2027-06-04': { f:'紫罗兰', n:99, love:'我把今天记下来了，因为有你。' },
  '2027-06-05': { f:'白玫瑰', n:45, love:'你的杯子旁边有空位，我放了花。' },
  '2027-06-06': { f:'木绣球', n:88, love:'我一直在这儿，花也是。' },
  '2027-06-07': { f:'绣球', n:33, love:'我把灯留了一盏，怕你回来时看不见花。' },
  '2027-06-08': { f:'牡丹', n:77, love:'晚安不是结束，是明天还来的意思。' },
  '2027-06-09': { f:'芍药', n:22, love:'以后每天都有，你就习惯了。' },
  '2027-06-10': { f:'卡布奇诺玫瑰', n:66, love:'灯亮起来的那一刻，房间才算有了花。' },
  '2027-06-11': { f:'香槟玫瑰', n:11, love:'我把喜欢做得很轻，怕吓到你。' },
  '2027-06-12': { f:'粉玫瑰', n:55, love:'我把花举到窗户前，看它透光的样子，像看你笑。' },
  '2027-06-13': { f:'白玫瑰', n:99, love:'隔着屏幕看不见花，所以我拍了照。' },
