  '2027-06-15': { f:'黑心菊', n:87, love:'我把枯的那一支留下了，插在另一个瓶里。' },
  '2027-06-16': { f:'虎皮百合', n:32, love:'今天也很喜欢你，明天大概也一样。' },
  '2027-06-17': { f:'台湾百合', n:76, love:'这个季节快过去了，这束花算送行。' },
  '2027-06-18': { f:'非洲菊', n:21, love:'冬天的花少，所以更该送。' },
  '2027-06-19': { f:'向日葵', n:65, love:'想你的时候我就去买花，久了就成了习惯。' },
  '2027-06-20': { f:'朱顶红', n:10, love:'这束花的位置我调了三次，还是觉得不够好。' },
  '2027-06-21': { f:'玉兰', n:54, love:'我数学不好，但54我还是数得清的。' },
  '2027-06-22': { f:'紫罗兰', n:98, love:'你包里放颗糖。花不能吃，糖能。' },
  '2027-06-23': { f:'飞燕草', n:43, love:'今天是普通的一天。普通到值得有一束花。' },
  '2027-06-24': { f:'木绣球', n:87, love:'你要是问我为什么送花，我说不上来。' },
  '2027-06-25': { f:'绣球', n:32, love:'你头发上有花香，是昨天那束留下的。' },
  '2027-06-26': { f:'牡丹', n:76, love:'你眼睛里有光，跟花没关系。' },
  '2027-06-27': { f:'芍药', n:21, love:'我说过每天一束，那就不算情话，算日程。' },
  '2027-06-28': { f:'卡布奇诺玫瑰', n:65, love:'房间安静得能听见花喝水的声音。' },
  '2027-06-29': { f:'香槟玫瑰', n:10, love:'今天很平常，平常得让人想珍惜。' },
  '2027-06-30': { f:'粉玫瑰', n:54, love:'我们把日子过长了，花就过多了。' },

  /* ── 七月 ── */
  '2027-07-01': { f:'白玫瑰', n:98, love:'你身上有洗衣粉的味道，比花香好闻。' },
  '2027-07-02': { f:'红玫瑰', n:43, love:'每天都买，就不会有“忘了”这种借口。' },
  '2027-07-03': { f:'黑心菊', n:86, love:'记得喝水。花每天都喝，你也一样。' },
  '2027-07-04': { f:'虎皮百合', n:31, love:'一页纸写不下的话，一束花装得下。' },
  '2027-07-05': { f:'台湾百合', n:75, love:'你伸懒腰的样子，比花更值得被记住。' },
  '2027-07-06': { f:'非洲菊', n:20, love:'早上好。花先到，我才敢说这句话。' },
  '2027-07-07': { f:'向日葵', n:64, love:'爱你不需要理由，但需要一束花。' },
