  /* ── 八月 ── */
  '2027-08-01': { f:'香槟玫瑰', n:75, love:'房间黑下来以后，花香反而更清楚。' },
  '2027-08-02': { f:'芍药', n:19, love:'风穿过花枝的声音，像你小声叫我名字。' },
