  '2027-08-07': { f:'红玫瑰', n:41, love:'愿你以后的日子里，花是常客。' },
  '2027-08-08': { f:'红玫瑰', n:52, love:'牛郎织女一年只见一次。我们不用。今天见完，明天我还来。' },
  '2027-08-09': { f:'虎皮百合', n:29, love:'糖放在抽屉第二格，花放在桌上第一眼。' },
  '2027-08-10': { f:'台湾百合', n:73, love:'泡面的三分钟，刚好够我看一眼花。' },
  '2027-08-11': { f:'非洲菊', n:18, love:'你在那边，我在这边，花在中间。' },
  '2027-08-12': { f:'向日葵', n:62, love:'冬天很长，花很短。所以每天都要买。' },
  '2027-08-13': { f:'朱顶红', n:7, love:'桌子有点乱，只有花是正的。' },
  '2027-08-14': { f:'玉兰', n:51, love:'明天还买。后天再说。' },
  '2027-08-15': { f:'紫罗兰', n:95, love:'城市这么大，我每天只走两条路：花店，和你。' },
  '2027-08-16': { f:'飞燕草', n:40, love:'书签是一朵压干的花，去年夹的。' },
  '2027-08-17': { f:'木绣球', n:84, love:'我把日子过成了一束一束的。' },
  '2027-08-18': { f:'绣球', n:29, love:'我把花上的水珠擦干了，怕弄湿你的手。' },
  '2027-08-19': { f:'牡丹', n:73, love:'书翻到哪页都行，花停在今天这页。' },
  '2027-08-20': { f:'芍药', n:18, love:'花的颜色我没挑，是它自己挑的。' },
  '2027-08-21': { f:'卡布奇诺玫瑰', n:62, love:'每天一束，是我给自己的规矩。' },
  '2027-08-22': { f:'香槟玫瑰', n:7, love:'你说家里快放不下了。那就换个大点的屋子。' },
  '2027-08-23': { f:'粉玫瑰', n:51, love:'有些话我说不出口，就让花说。' },
  '2027-08-24': { f:'白玫瑰', n:95, love:'雨天路滑，你慢一点。花不急，我也不急。' },
  '2027-08-25': { f:'红玫瑰', n:40, love:'我把花放低了一点，你坐着也能看见。' },
  '2027-08-26': { f:'黑心菊', n:83, love:'今天差点忘了。还好想起来了。' },
  '2027-08-27': { f:'虎皮百合', n:28, love:'我把闹钟调早了十分钟，只为多看一眼今天的花。' },
  '2027-08-28': { f:'台湾百合', n:72, love:'你的名字三个字，我念了72遍。' },
  '2027-08-29': { f:'白玫瑰', n:18, love:'数到18的时候我停了，再多就说不清了。' },
