  '2029-05-22': { f:'飞燕草', n:92, love:'有些花只开一天。所以今天必须送。' },
  '2029-05-23': { f:'木绣球', n:37, love:'你包里放颗糖。花不能吃，糖能。' },
  '2029-05-24': { f:'绣球', n:81, love:'你把它摆在窗边，我看见了。' },
  '2029-05-25': { f:'牡丹', n:26, love:'我们还有很长的日子，够放很多束花。' },
  '2029-05-26': { f:'芍药', n:70, love:'雨停之后会有味道，那是我想让你闻到的。' },
  '2029-05-27': { f:'卡布奇诺玫瑰', n:15, love:'灯亮起来的那一刻，房间才算有了花。' },
  '2029-05-28': { f:'香槟玫瑰', n:59, love:'你手凉，握花之前先搓一搓。' },
  '2029-05-29': { f:'白玫瑰', n:5, love:'你嫌麻烦的话，我可以不送。但我不会。' },
  '2029-05-30': { f:'白玫瑰', n:48, love:'雪停以后，世界很白，只有这束花是活的。' },
  '2029-05-31': { f:'红玫瑰', n:92, love:'它开得不算完美，可它是今天的。' },

  /* ── 六月 ── */
  '2029-06-01': { f:'黑心菊', n:36, love:'我把喜欢你藏在花里，你找找看。' },
  '2029-06-02': { f:'虎皮百合', n:80, love:'等待也是爱的一部分，我认了。' },
  '2029-06-03': { f:'台湾百合', n:25, love:'房间安静得能听见花喝水的声音。' },
  '2029-06-04': { f:'非洲菊', n:69, love:'一天一束，是我能想到最笨也最实的表达。' },
  '2029-06-05': { f:'红玫瑰', n:15, love:'今天的花是老板推荐的，他说适合送人。' },
  '2029-06-06': { f:'朱顶红', n:58, love:'花瓣边缘有点卷，那是它认真开过的证据。' },
  '2029-06-07': { f:'玉兰', n:3, love:'窗外下雨，屋里有一束不该这么亮的花。' },
  '2029-06-08': { f:'红玫瑰', n:48, love:'夜里回家，看到窗口有花，就像看到你。' },
  '2029-06-09': { f:'飞燕草', n:91, love:'窗帘拉开的时候，替我看一眼花。' },
  '2029-06-10': { f:'木绣球', n:36, love:'这束花有点歪，我觉得挺好，正的不像话。' },
  '2029-06-11': { f:'绣球', n:80, love:'春天该有花，夏天也是，秋天冬天都是。' },
  '2029-06-12': { f:'牡丹', n:25, love:'我把枯的那一支留下了，插在另一个瓶里。' },
  '2029-06-13': { f:'芍药', n:69, love:'热水烧上了。花也摆好了。就等你。' },
  '2029-06-14': { f:'白玫瑰', n:15, love:'秋天适合把话说慢一点。' },
  '2029-06-15': { f:'香槟玫瑰', n:58, love:'我把买花写进了日程，排在所有事前面。' },
  '2029-06-16': { f:'粉玫瑰', n:3, love:'我准备了很多话，最后只递过去一束花。' },
  '2029-06-17': { f:'粉玫瑰', n:48, love:'爱你不需要理由，但需要一束花。' },
  '2029-06-18': { f:'红玫瑰', n:91, love:'我挑了很久，最后拿了最像你的那一束。' },
  '2029-06-19': { f:'黑心菊', n:35, love:'我词穷的时候，花替我开口。' },
  '2029-06-20': { f:'虎皮百合', n:79, love:'愿你今天笑得比昨天多一次。' },
  '2029-06-21': { f:'台湾百合', n:24, love:'我记性不好，只记得两件事：买花，和你。' },
  '2029-06-22': { f:'非洲菊', n:68, love:'早安。这两个字我说了一千次，还是想再说。' },
  '2029-06-23': { f:'向日葵', n:13, love:'我把花放在光里，让它先替你晒一会儿。' },
  '2029-06-24': { f:'朱顶红', n:57, love:'我一进门先看花，再看有没有你的鞋。' },
  '2029-06-25': { f:'玉兰', n:2, love:'我把手机调暗了，怕吵到花，也怕吵到你。' },
  '2029-06-26': { f:'紫罗兰', n:46, love:'天冷了。我把花挪到离暖气近一点的地方。' },
  '2029-06-27': { f:'飞燕草', n:90, love:'明天的花已经在路上了，你不用担心。' },
  '2029-06-28': { f:'木绣球', n:35, love:'愿你偶尔想起我，就够了。' },
  '2029-06-29': { f:'绣球', n:79, love:'记得喝水。花每天都喝，你也一样。' },
  '2029-06-30': { f:'牡丹', n:24, love:'安静的爱也算爱，而且更耐放。' },

  /* ── 七月 ── */
  '2029-07-01': { f:'芍药', n:68, love:'剪口要斜着剪，它才喝得进水。人也一样。' },
  '2029-07-02': { f:'卡布奇诺玫瑰', n:13, love:'你今天回不回？花在门口站了一天。' },
  '2029-07-03': { f:'香槟玫瑰', n:57, love:'刮风了，记得关窗。花怕吹，我也怕你冷。' },
  '2029-07-04': { f:'粉玫瑰', n:2, love:'数到2的时候我停了，再多就说不清了。' },
  '2029-07-05': { f:'白玫瑰', n:46, love:'这座城每天都不一样，我只做同一件事。' },
  '2029-07-06': { f:'红玫瑰', n:90, love:'窗台空了很久，今天有花了。' },
  '2029-07-07': { f:'黑心菊', n:34, love:'数字不重要，重要的是每天都数。' },
  '2029-07-08': { f:'虎皮百合', n:78, love:'今天的花配今天的茶，明天换一种。' },
  '2029-07-09': { f:'台湾百合', n:23, love:'到家记得先放下包，再看花。' },
  '2029-07-10': { f:'非洲菊', n:67, love:'夜里我数了一遍花瓣，数到你就停了。' },
  '2029-07-11': { f:'向日葵', n:12, love:'你戴围巾的样子，比花耐看。' },
  '2029-07-12': { f:'朱顶红', n:56, love:'这件事我做了很多天，还会做很多天。' },
  '2029-07-13': { f:'玉兰', n:1, love:'一天一束，一年就是三百多束。' },
  '2029-07-14': { f:'紫罗兰', n:45, love:'你上次说喜欢这种颜色，我记住了。' },
  '2029-07-15': { f:'飞燕草', n:89, love:'我把话都放轻了，怕吵醒这束花。' },
  '2029-07-16': { f:'木绣球', n:34, love:'雪落在窗台上，花落在光里，我落在想你里。' },
  '2029-07-17': { f:'绣球', n:78, love:'愿你今天醒来，先想起的是花，再想起是我。' },
  '2029-07-18': { f:'牡丹', n:23, love:'我把“每天”这两个字，做成了具体的东西。' },
  '2029-07-19': { f:'芍药', n:67, love:'我在这里，你在那里，花在中间跑腿。' },
  '2029-07-20': { f:'卡布奇诺玫瑰', n:12, love:'你不在的时候，我把花摆在你常坐的位置。' },
  '2029-07-21': { f:'香槟玫瑰', n:56, love:'一直送到你嫌烦为止。到时候我换一种花。' },
  '2029-07-22': { f:'粉玫瑰', n:1, love:'雨天路滑，你慢一点。花不急，我也不急。' },
  '2029-07-23': { f:'粉玫瑰', n:45, love:'说不出为什么，就觉得今天该有花。' },
  '2029-07-24': { f:'红玫瑰', n:89, love:'下雪天不想出门。可花已经在路上了。' },
  '2029-07-25': { f:'黑心菊', n:33, love:'愿你晚上睡个好觉，梦里没有工作。' },
  '2029-07-26': { f:'虎皮百合', n:77, love:'我离你有点远，花离你很近。' },
  '2029-07-27': { f:'台湾百合', n:22, love:'今天不在你身边，明天补上。' },
  '2029-07-28': { f:'非洲菊', n:66, love:'信纸有香味，花也有。分不清哪个是你。' },
  '2029-07-29': { f:'向日葵', n:11, love:'你收到花的时候，会先闻一下吗。' },
  '2029-07-30': { f:'朱顶红', n:55, love:'房间很小，一束花就满了。像你一来，我就满。' },
  '2029-07-31': { f:'玉兰', n:99, love:'你不用担心哪天没有花。那件事不会发生。' },

  /* ── 八月 ── */
  '2029-08-01': { f:'香槟玫瑰', n:45, love:'碗我来洗。你去看看花。' },
  '2029-08-02': { f:'飞燕草', n:88, love:'手冷的话，先握花，再握我。' },
  '2029-08-03': { f:'木绣球', n:33, love:'我把想说的话写下来，又撕了，改买花。' },
  '2029-08-04': { f:'绣球', n:77, love:'风大的日子，我把花放在屋里，把想你放在外面。' },
  '2029-08-05': { f:'牡丹', n:22, love:'今天是普通的一天。普通到值得有一束花。' },
