  '2029-08-07': { f:'卡布奇诺玫瑰', n:11, love:'我把话咽回去了，换成一束花。' },
  '2029-08-08': { f:'香槟玫瑰', n:55, love:'沉默有时候也是回答，花就是。' },
  '2029-08-09': { f:'粉玫瑰', n:99, love:'你今天读了什么？我读了一束花。' },
  '2029-08-10': { f:'卡布奇诺玫瑰', n:45, love:'我把你的名字念给花听，它好像听懂了。' },
  '2029-08-11': { f:'红玫瑰', n:88, love:'你收花的表情，比花好看。' },
  '2029-08-12': { f:'黑心菊', n:32, love:'我把花放低了一点，你坐着也能看见。' },
  '2029-08-13': { f:'虎皮百合', n:76, love:'我不保证永远，我只保证明天还有。' },
  '2029-08-14': { f:'台湾百合', n:21, love:'花店里有只猫，它比你还不理人。' },
  '2029-08-15': { f:'非洲菊', n:65, love:'你说话的时候，我在看你的手。' },
  '2029-08-16': { f:'红玫瑰', n:52, love:'牛郎织女一年只见一次。我们不用。今天见完，明天我还来。' },
  '2029-08-17': { f:'朱顶红', n:54, love:'你的肩膀今天有点塌，是不是累了。' },
  '2029-08-18': { f:'玉兰', n:98, love:'我不擅长开口，但我擅长坚持。' },
  '2029-08-19': { f:'紫罗兰', n:43, love:'回家的路上买了一束花，路就不算白走。' },
  '2029-08-20': { f:'飞燕草', n:87, love:'出门带伞。花不能带，我可以。' },
  '2029-08-21': { f:'木绣球', n:32, love:'我不是不想说，是说了怕你为难。' },
  '2029-08-22': { f:'绣球', n:76, love:'明年这个时候，花会更多。' },
  '2029-08-23': { f:'牡丹', n:21, love:'夜深了。花还醒着，我也还醒着。' },
  '2029-08-24': { f:'芍药', n:65, love:'等人的时候，时间会变得很具体。' },
  '2029-08-25': { f:'卡布奇诺玫瑰', n:10, love:'早晨很短。我想把它全用来想你，剩下的才用来做事。' },
  '2029-08-26': { f:'香槟玫瑰', n:54, love:'我叫你的时候，语气会不自觉轻一点。' },
  '2029-08-27': { f:'粉玫瑰', n:98, love:'影子会被拉长，想你这件事不会。' },
  '2029-08-28': { f:'白玫瑰', n:43, love:'你眼睛里有光，跟花没关系。' },
  '2029-08-29': { f:'红玫瑰', n:87, love:'我们之间不用很多话，花就够了。' },
  '2029-08-30': { f:'黑心菊', n:31, love:'夏天太热，花蔫得快，我每天换水。' },
  '2029-08-31': { f:'虎皮百合', n:75, love:'黄昏最长。足够我把想你这件事做完一遍。' },

  /* ── 九月 ── */
  '2029-09-01': { f:'台湾百合', n:20, love:'我要的不是每天都见，是每天都想。' },
  '2029-09-02': { f:'非洲菊', n:64, love:'你吃饭了吗？这句话我一天想问三遍。' },
  '2029-09-03': { f:'向日葵', n:9, love:'老板说这种花不耐放，我说没关系，明天再来。' },
  '2029-09-04': { f:'朱顶红', n:53, love:'你头发上有花香，是昨天那束留下的。' },
  '2029-09-05': { f:'玉兰', n:97, love:'我不喜欢热闹，只喜欢你在的那点安静。' },
  '2029-09-06': { f:'紫罗兰', n:42, love:'今天没见到你，花替我进去了。' },
  '2029-09-07': { f:'飞燕草', n:86, love:'这个季节快过去了，这束花算送行。' },
  '2029-09-08': { f:'木绣球', n:31, love:'今天没什么惊喜，只有一束花。' },
  '2029-09-09': { f:'绣球', n:75, love:'你今天有没有一刻，也想起我。' },
  '2029-09-10': { f:'牡丹', n:20, love:'愿你今晚不做噩梦，梦里也有花香。' },
  '2029-09-11': { f:'芍药', n:64, love:'你收到的每一束，都是当天的。' },
  '2029-09-12': { f:'卡布奇诺玫瑰', n:9, love:'我打算买到我们都不好意思为止。' },
  '2029-09-13': { f:'香槟玫瑰', n:53, love:'你把它插在哪了？我想知道。' },
  '2029-09-14': { f:'粉玫瑰', n:97, love:'我煮了面，多打了一个蛋，像多买一支花。' },
  '2029-09-15': { f:'白玫瑰', n:42, love:'你走的时候带起一阵风，花到现在还没站直。' },
  '2029-09-16': { f:'红玫瑰', n:86, love:'我从不觉得这是负担，倒像每天要吃饭。' },
  '2029-09-17': { f:'黑心菊', n:30, love:'我每次都说随便包一下，其实挑了很久。' },
  '2029-09-18': { f:'粉玫瑰', n:75, love:'我把花举到窗户前，看它透光的样子，像看你笑。' },
  '2029-09-19': { f:'台湾百合', n:19, love:'有刺。可它把刺朝着自己。' },
  '2029-09-20': { f:'非洲菊', n:63, love:'睡前想起你，像关灯前多看了一眼花。' },
  '2029-09-21': { f:'向日葵', n:8, love:'我把花放在门口，按了铃就走。' },
  '2029-09-22': { f:'朱顶红', n:52, love:'我们把日子过长了，花就过多了。' },
  '2029-09-23': { f:'玉兰', n:96, love:'我买花从不讲价，怕显得不够诚心。' },
  '2029-09-24': { f:'紫罗兰', n:41, love:'承诺太轻，所以我改成每天做一遍。' },
  '2029-09-25': { f:'飞燕草', n:85, love:'今天差点忘了。还好想起来了。' },
  '2029-09-26': { f:'木绣球', n:30, love:'愿你想起这束花的时候，是笑着的。' },
  '2029-09-27': { f:'香槟玫瑰', n:75, love:'秋天的花贵一点，我还是买了。' },
  '2029-09-28': { f:'牡丹', n:19, love:'窗外是车流，窗内是一束花。' },
  '2029-09-29': { f:'芍药', n:63, love:'时间不站在任何人那边，花也不。所以今天要送。' },
  '2029-09-30': { f:'卡布奇诺玫瑰', n:8, love:'你的名字我写在花束的卡片背面了。' },

  /* ── 十月 ── */
  '2029-10-01': { f:'香槟玫瑰', n:52, love:'书签是一朵压干的花，去年夹的。' },
  '2029-10-02': { f:'粉玫瑰', n:96, love:'城市这么大，我每天只走两条路：花店，和你。' },
  '2029-10-03': { f:'白玫瑰', n:41, love:'起风了。我想起你，也想起该收衣服了。' },
  '2029-10-04': { f:'红玫瑰', n:85, love:'喜欢你这件事，我做得最久。' },
  '2029-10-05': { f:'黑心菊', n:29, love:'我数学不好，但29我还是数得清的。' },
  '2029-10-06': { f:'虎皮百合', n:73, love:'我把日子过成了一束一束的。' },
  '2029-10-07': { f:'台湾百合', n:18, love:'花不说话，但它记得被谁抱过。' },
  '2029-10-08': { f:'非洲菊', n:62, love:'安静地爱你，是我最擅长的事。' },
  '2029-10-09': { f:'向日葵', n:7, love:'我把花上的水珠擦干了，怕弄湿你的手。' },
  '2029-10-10': { f:'朱顶红', n:51, love:'你说这束好看。那明天我也买这种。' },
  '2029-10-11': { f:'玉兰', n:95, love:'我不能每天都见到你，但花能。' },
  '2029-10-12': { f:'紫罗兰', n:40, love:'风把窗帘吹起来的时候，花点了点头。' },
  '2029-10-13': { f:'飞燕草', n:84, love:'84是今天的数字，明天会不一样。' },
  '2029-10-14': { f:'木绣球', n:29, love:'雨停之前，先让花替我说完。' },
  '2029-10-15': { f:'绣球', n:73, love:'花店老板问我今天送谁，我说还是那个人。' },
  '2029-10-16': { f:'牡丹', n:18, love:'我把今天过完了，只剩想你没做。' },
  '2029-10-17': { f:'芍药', n:62, love:'你笑起来的时候，花就不算什么了。' },
  '2029-10-18': { f:'卡布奇诺玫瑰', n:7, love:'花会谢，这件事不会。' },
  '2029-10-19': { f:'香槟玫瑰', n:51, love:'风穿过花枝的声音，像你小声叫我名字。' },
  '2029-10-20': { f:'粉玫瑰', n:95, love:'我没有什么新闻，只有一束花。' },
  '2029-10-21': { f:'白玫瑰', n:40, love:'路过便利店，顺手买了瓶新的水给花。' },
  '2029-10-22': { f:'红玫瑰', n:84, love:'你把它养几天吧，别急着扔。' },
  '2029-10-23': { f:'黑心菊', n:28, love:'冬天很长，花很短。所以每天都要买。' },
