  '2030-07-31': { f:'向日葵', n:39, love:'很远也没关系，花是寄过去的。' },

  /* ── 八月 ── */
  '2030-08-01': { f:'朱顶红', n:83, love:'我不擅长计划未来，但这个计划我做好了。' },
  '2030-08-02': { f:'玉兰', n:28, love:'早晨很短。我想把它全用来想你，剩下的才用来做事。' },
  '2030-08-03': { f:'紫罗兰', n:72, love:'楼下的花店老板已经认识我了。' },
  '2030-08-04': { f:'香槟玫瑰', n:18, love:'秋天适合把话说慢一点。' },
  '2030-08-05': { f:'红玫瑰', n:52, love:'牛郎织女一年只见一次。我们不用。今天见完，明天我还来。' },
  '2030-08-06': { f:'绣球', n:6, love:'我买花从不讲价，怕显得不够诚心。' },
  '2030-08-07': { f:'牡丹', n:50, love:'明年今日，我还会站在同一个花店。' },
  '2030-08-08': { f:'芍药', n:94, love:'夜里我数了一遍花瓣，数到你就停了。' },
  '2030-08-09': { f:'卡布奇诺玫瑰', n:39, love:'刮风了，记得关窗。花怕吹，我也怕你冷。' },
  '2030-08-10': { f:'香槟玫瑰', n:83, love:'承诺太轻，所以我改成每天做一遍。' },
  '2030-08-11': { f:'粉玫瑰', n:28, love:'愿你被这个世界善待，剩下的我来补。' },
  '2030-08-12': { f:'白玫瑰', n:72, love:'我把闹钟调早了十分钟，只为多看一眼今天的花。' },
  '2030-08-13': { f:'卡布奇诺玫瑰', n:18, love:'我记住了那家店的位置，也记住了你的。' },
  '2030-08-14': { f:'黑心菊', n:60, love:'风大的日子，我把花放在屋里，把想你放在外面。' },
  '2030-08-15': { f:'虎皮百合', n:5, love:'你说话的时候，我在看你的手。' },
  '2030-08-16': { f:'台湾百合', n:49, love:'今天光很好。我想和你一起浪费掉。' },
  '2030-08-17': { f:'非洲菊', n:93, love:'隔着一段路，我把花先送过去。' },
  '2030-08-18': { f:'向日葵', n:38, love:'我数过，38支。多一支我怕你嫌多。' },
  '2030-08-19': { f:'朱顶红', n:82, love:'我一进门先看花，再看有没有你的鞋。' },
  '2030-08-20': { f:'玉兰', n:27, love:'泡面的三分钟，刚好够我看一眼花。' },
  '2030-08-21': { f:'紫罗兰', n:71, love:'你戴围巾的样子，比花耐看。' },
  '2030-08-22': { f:'飞燕草', n:16, love:'隔着屏幕看不见花，所以我拍了照。' },
  '2030-08-23': { f:'木绣球', n:60, love:'花店七点关门，我六点五十到。' },
  '2030-08-24': { f:'绣球', n:5, love:'说不出为什么，就觉得今天该有花。' },
  '2030-08-25': { f:'牡丹', n:49, love:'数到49的时候我停了，再多就说不清了。' },
  '2030-08-26': { f:'芍药', n:93, love:'我在路口等了两分钟，花在怀里等了一路。' },
  '2030-08-27': { f:'卡布奇诺玫瑰', n:38, love:'地铁很挤，只有花是站着的。' },
  '2030-08-28': { f:'香槟玫瑰', n:82, love:'你今天晚了半小时，花都没蔫。' },
  '2030-08-29': { f:'粉玫瑰', n:27, love:'我把花递过去的时候，碰到了你的手指。' },
  '2030-08-30': { f:'白玫瑰', n:71, love:'花瓣掉了一片在桌上，我没扫。' },
  '2030-08-31': { f:'红玫瑰', n:16, love:'我词穷的时候，花替我开口。' },

  /* ── 九月 ── */
  '2030-09-01': { f:'黑心菊', n:59, love:'今天这束是第几束我不知道，反正不是最后一束。' },
