  '2031-02-09': { f:'牡丹', n:99, love:'门开着的时候，风把花香送进去了。' },
  '2031-02-10': { f:'白玫瑰', n:45, love:'我把枯的那一支留下了，插在另一个瓶里。' },
  '2031-02-11': { f:'卡布奇诺玫瑰', n:88, love:'这座城有一万家店，我只进那一家。' },
  '2031-02-12': { f:'香槟玫瑰', n:33, love:'你走之后，屋里最响的是花香。' },
  '2031-02-13': { f:'粉玫瑰', n:77, love:'我把花揣在怀里跑了一路，怕它淋着，像怕你冷。' },
  '2031-02-14': { f:'红玫瑰', n:99, love:'情人节一年只有一天，可爱你这件事，我打算做满三百六十五天。' },
  '2031-02-15': { f:'红玫瑰', n:66, love:'今天的花比昨天的那束精神一点。' },
  '2031-02-16': { f:'黑心菊', n:10, love:'窗外是车流，窗内是一束花。' },
  '2031-02-17': { f:'虎皮百合', n:54, love:'秋天适合把话说慢一点。' },
  '2031-02-18': { f:'台湾百合', n:98, love:'明年这个时候，花会更多。' },
  '2031-02-19': { f:'非洲菊', n:43, love:'花瓣掉了一片在桌上，我没扫。' },
  '2031-02-20': { f:'向日葵', n:87, love:'日子过得很快，花换得很慢。' },
  '2031-02-21': { f:'朱顶红', n:32, love:'隔着一段路，我把花先送过去。' },
  '2031-02-22': { f:'玉兰', n:76, love:'你今天走得急，花替你多看了一会儿门。' },
  '2031-02-23': { f:'紫罗兰', n:21, love:'我在这里，你在那里，花在中间跑腿。' },
  '2031-02-24': { f:'飞燕草', n:65, love:'雨把城市洗了一遍，我把花擦了一遍。' },
  '2031-02-25': { f:'木绣球', n:10, love:'你不在的时候，我把花摆在你常坐的位置。' },
  '2031-02-26': { f:'绣球', n:54, love:'我把花靠在门边，它站得很直。' },
  '2031-02-27': { f:'牡丹', n:98, love:'我把今天过完了，只剩想你没做。' },
  '2031-02-28': { f:'芍药', n:43, love:'出门带伞。花不能带，我可以。' },

  /* ── 三月 ── */
  '2031-03-01': { f:'卡布奇诺玫瑰', n:87, love:'手冷的话，先握花，再握我。' },
  '2031-03-02': { f:'香槟玫瑰', n:32, love:'我不喜欢热闹，只喜欢你在的那点安静。' },
  '2031-03-03': { f:'粉玫瑰', n:76, love:'今天的花有点贵，我觉得值。' },
  '2031-03-04': { f:'白玫瑰', n:21, love:'我把想说的话写下来，又撕了，改买花。' },
  '2031-03-05': { f:'红玫瑰', n:65, love:'你收到花的时候，会先闻一下吗。' },
  '2031-03-06': { f:'黑心菊', n:9, love:'我买花从不讲价，怕显得不够诚心。' },
  '2031-03-07': { f:'虎皮百合', n:53, love:'我词穷的时候，花替我开口。' },
