  '2031-03-09': { f:'非洲菊', n:42, love:'你说话的时候，我在看你的手。' },
  '2031-03-10': { f:'向日葵', n:86, love:'我从不觉得这是负担，倒像每天要吃饭。' },
  '2031-03-11': { f:'朱顶红', n:31, love:'我不敢当面叫你，就在心里叫了很多遍。' },
  '2031-03-12': { f:'玉兰', n:75, love:'刮风了，记得关窗。花怕吹，我也怕你冷。' },
  '2031-03-13': { f:'紫罗兰', n:20, love:'今天没下雨，花一路都很好。' },
  '2031-03-14': { f:'飞燕草', n:64, love:'门关上的声音，比什么都空。' },
  '2031-03-15': { f:'木绣球', n:9, love:'我把灯留了一盏，怕你回来时看不见花。' },
  '2031-03-16': { f:'绣球', n:53, love:'你醒来的那一刻，这束花就白等了半宿——它想第一个看见你。' },
  '2031-03-17': { f:'牡丹', n:97, love:'风把窗帘吹起来的时候，花点了点头。' },
  '2031-03-18': { f:'芍药', n:42, love:'我把花放低了一点，你坐着也能看见。' },
  '2031-03-19': { f:'卡布奇诺玫瑰', n:86, love:'我把今天记下来了，因为有你。' },
  '2031-03-20': { f:'香槟玫瑰', n:31, love:'城市这么大，我每天只走两条路：花店，和你。' },
  '2031-03-21': { f:'粉玫瑰', n:75, love:'它开得不算完美，可它是今天的。' },
  '2031-03-22': { f:'白玫瑰', n:20, love:'我把闹钟调早了十分钟，只为多看一眼今天的花。' },
  '2031-03-23': { f:'红玫瑰', n:64, love:'数字不重要，重要的是每天都数。' },
  '2031-03-24': { f:'黑心菊', n:8, love:'我煮了面，多打了一个蛋，像多买一支花。' },
  '2031-03-25': { f:'虎皮百合', n:52, love:'52支，我数了两遍，怕少。' },
  '2031-03-26': { f:'台湾百合', n:96, love:'96是今天的数字，明天会不一样。' },
  '2031-03-27': { f:'非洲菊', n:41, love:'今天的第一件事不是刷牙，是想你。' },
  '2031-03-28': { f:'向日葵', n:85, love:'秋天的花贵一点，我还是买了。' },
