  '2031-03-30': { f:'红玫瑰', n:75, love:'我们把日子过长了，花就过多了。' },
  '2031-03-31': { f:'紫罗兰', n:19, love:'春天该有花，夏天也是，秋天冬天都是。' },

  /* ── 四月 ── */
  '2031-04-01': { f:'飞燕草', n:63, love:'今天的天气配这束花，刚刚好。' },
  '2031-04-02': { f:'木绣球', n:8, love:'桌子有点乱，只有花是正的。' },
  '2031-04-03': { f:'绣球', n:52, love:'我把花放在光里，让它先替你晒一会儿。' },
  '2031-04-04': { f:'牡丹', n:96, love:'我不擅长开口，但我擅长坚持。' },
  '2031-04-05': { f:'芍药', n:41, love:'冬天买花的人少，所以这束更显眼，像我。' },
  '2031-04-06': { f:'卡布奇诺玫瑰', n:85, love:'夏天太热，花蔫得快，我每天换水。' },
