  '2031-04-30': { f:'虎皮百合', n:50, love:'热水烧上了。花也摆好了。就等你。' },

  /* ── 五月 ── */
  '2031-05-01': { f:'台湾百合', n:94, love:'我不能每天都见到你，但花能。' },
