  '2031-07-16': { f:'玉兰', n:68, love:'你在那边，我在这边，花在中间。' },
  '2031-07-17': { f:'紫罗兰', n:13, love:'你眼睛里有光，跟花没关系。' },
  '2031-07-18': { f:'飞燕草', n:57, love:'我不懂浪漫，我只是每天做同一件小事。' },
  '2031-07-19': { f:'木绣球', n:2, love:'你伸懒腰的样子，比花更值得被记住。' },
  '2031-07-20': { f:'绣球', n:46, love:'每天都不一样，只有这件事一样。' },
  '2031-07-21': { f:'牡丹', n:90, love:'我把买花写进了日程，排在所有事前面。' },
  '2031-07-22': { f:'芍药', n:35, love:'等的时候我数花瓣，数完就差不多到了。' },
  '2031-07-23': { f:'卡布奇诺玫瑰', n:79, love:'你不问，我就不说。花替我说。' },
  '2031-07-24': { f:'香槟玫瑰', n:24, love:'你多久没收到花了？太久了。' },
  '2031-07-25': { f:'粉玫瑰', n:68, love:'走过花店的时候，我总会慢半步。' },
  '2031-07-26': { f:'白玫瑰', n:13, love:'夜里我数了一遍花瓣，数到你就停了。' },
  '2031-07-27': { f:'红玫瑰', n:57, love:'你把它摆在窗边，我看见了。' },
  '2031-07-28': { f:'黑心菊', n:1, love:'我不催你。花也不催。' },
  '2031-07-29': { f:'虎皮百合', n:45, love:'今天光很好。我想和你一起浪费掉。' },
  '2031-07-30': { f:'台湾百合', n:89, love:'我把花抱在胸前，像抱着一句没说出口的话。' },
  '2031-07-31': { f:'非洲菊', n:34, love:'这座城每天都不一样，我只做同一件事。' },

  /* ── 八月 ── */
  '2031-08-01': { f:'向日葵', n:78, love:'花会谢，这件事不会。' },
  '2031-08-02': { f:'朱顶红', n:23, love:'你还没醒，花已经替我说过一遍早安了。' },
  '2031-08-03': { f:'玉兰', n:67, love:'天冷了。我把花挪到离暖气近一点的地方。' },
  '2031-08-04': { f:'紫罗兰', n:12, love:'你今天会来吗。花已经问过一遍了。' },
  '2031-08-05': { f:'飞燕草', n:56, love:'雪停以后，世界很白，只有这束花是活的。' },
  '2031-08-06': { f:'木绣球', n:1, love:'一年之后，这束花会变成很多束。' },
  '2031-08-07': { f:'绣球', n:45, love:'你回家开门的那一下，花会先亮起来。' },
  '2031-08-08': { f:'牡丹', n:89, love:'我不擅长长期，除了这一件。' },
  '2031-08-09': { f:'芍药', n:34, love:'风大的日子，我把花放在屋里，把想你放在外面。' },
  '2031-08-10': { f:'卡布奇诺玫瑰', n:78, love:'我没有一次是顺路买的，都是专门去的。' },
  '2031-08-11': { f:'香槟玫瑰', n:23, love:'我写字不好看，所以让花替我说。' },
  '2031-08-12': { f:'粉玫瑰', n:67, love:'你说家里快放不下了。那就换个大点的屋子。' },
  '2031-08-13': { f:'白玫瑰', n:12, love:'明年今日，我还会站在同一个花店。' },
  '2031-08-14': { f:'红玫瑰', n:56, love:'喜欢是藏不住的，所以我干脆每天送。' },
  '2031-08-15': { f:'黑心菊', n:99, love:'房间很小，一束花就满了。像你一来，我就满。' },
  '2031-08-16': { f:'粉玫瑰', n:45, love:'愿你什么都好，包括不告诉我。' },
  '2031-08-17': { f:'台湾百合', n:88, love:'你抬手的动作，像在接一束花。' },
  '2031-08-18': { f:'非洲菊', n:33, love:'门铃响了两声，我在楼下听着。' },
  '2031-08-19': { f:'向日葵', n:77, love:'今天是普通的一天。普通到值得有一束花。' },
  '2031-08-20': { f:'朱顶红', n:22, love:'起风了。我想起你，也想起该收衣服了。' },
  '2031-08-21': { f:'玉兰', n:66, love:'等人的时候，时间会变得很具体。' },
  '2031-08-22': { f:'紫罗兰', n:11, love:'我说过每天一束，那就不算情话，算日程。' },
  '2031-08-23': { f:'飞燕草', n:55, love:'我把花放在桌上，然后开始想你。' },
  '2031-08-24': { f:'红玫瑰', n:52, love:'牛郎织女一年只见一次。我们不用。今天见完，明天我还来。' },
  '2031-08-25': { f:'香槟玫瑰', n:45, love:'我不是不想说，是说了怕你为难。' },
  '2031-08-26': { f:'牡丹', n:88, love:'我把花摆在你看得到的地方，剩下的交给它。' },
  '2031-08-27': { f:'牡丹', n:33, love:'春天的花最吵，夏天的最甜。' },
  '2031-08-28': { f:'卡布奇诺玫瑰', n:77, love:'有些花只开一天。所以今天必须送。' },
  '2031-08-29': { f:'香槟玫瑰', n:22, love:'坚持这件事，我只对花和你认真过。' },
  '2031-08-30': { f:'粉玫瑰', n:66, love:'数到66的时候我停了，再多就说不清了。' },
  '2031-08-31': { f:'白玫瑰', n:11, love:'我一直在这儿，花也是。' },

  /* ── 九月 ── */
  '2031-09-01': { f:'红玫瑰', n:55, love:'回家的路上买了一束花，路就不算白走。' },
  '2031-09-02': { f:'黑心菊', n:98, love:'明天还买。后天再说。' },
  '2031-09-03': { f:'虎皮百合', n:43, love:'你说雨天心情不好。我把花放在你门口了。' },
  '2031-09-04': { f:'台湾百合', n:87, love:'你吃饭了吗？这句话我一天想问三遍。' },
  '2031-09-05': { f:'非洲菊', n:32, love:'今天到此为止。明天继续。' },
  '2031-09-06': { f:'向日葵', n:76, love:'花放在你桌上，占了半个屏幕的位置。值得。' },
  '2031-09-07': { f:'朱顶红', n:21, love:'如果清晨有味道，大概是你头发上那点洗衣粉。' },
  '2031-09-08': { f:'玉兰', n:65, love:'你把它养几天吧，别急着扔。' },
  '2031-09-09': { f:'紫罗兰', n:10, love:'说一辈子太满，我先做一年给你看。' },
  '2031-09-10': { f:'飞燕草', n:54, love:'加班的夜里，花在桌上替我陪着。' },
  '2031-09-11': { f:'木绣球', n:98, love:'雨声像有人在轻轻敲门。我去开，是你。' },
  '2031-09-12': { f:'绣球', n:43, love:'你身上有洗衣粉的味道，比花香好闻。' },
  '2031-09-13': { f:'牡丹', n:87, love:'你手凉，握花之前先搓一搓。' },
  '2031-09-14': { f:'芍药', n:32, love:'我想和你过很多个普通的明天。' },
  '2031-09-15': { f:'卡布奇诺玫瑰', n:76, love:'今天走了很多路，花一直在我手里。' },
  '2031-09-16': { f:'香槟玫瑰', n:21, love:'花在瓶里等，我在门口等，你总会来。' },
  '2031-09-17': { f:'粉玫瑰', n:65, love:'今天没能当面给你，只好先放在这儿。' },
  '2031-09-18': { f:'白玫瑰', n:10, love:'隔着屏幕看不见花，所以我拍了照。' },
  '2031-09-19': { f:'红玫瑰', n:54, love:'你要是问我为什么送花，我说不上来。' },
  '2031-09-20': { f:'黑心菊', n:97, love:'我在这个城市没什么牵挂，除了你。' },
  '2031-09-21': { f:'虎皮百合', n:42, love:'愿你被这个世界善待，剩下的我来补。' },
  '2031-09-22': { f:'台湾百合', n:86, love:'夜里回家，看到窗口有花，就像看到你。' },
  '2031-09-23': { f:'非洲菊', n:31, love:'早上好。花先到，我才敢说这句话。' },
  '2031-09-24': { f:'向日葵', n:75, love:'我等过很多次，都等到了。' },
  '2031-09-25': { f:'朱顶红', n:20, love:'我每次都说随便包一下，其实挑了很久。' },
  '2031-09-26': { f:'玉兰', n:64, love:'我不擅长表达，所以一天一束，积少成多。' },
  '2031-09-27': { f:'紫罗兰', n:9, love:'今天是第几天？我没数，反正都会买。' },
  '2031-09-28': { f:'飞燕草', n:53, love:'冬天过去就好了。花会先知道。' },
  '2031-09-29': { f:'木绣球', n:97, love:'时间从不回头，花也不。所以别等。' },
  '2031-09-30': { f:'绣球', n:42, love:'每天都买，就不会有“忘了”这种借口。' },

  /* ── 十月 ── */
  '2031-10-01': { f:'牡丹', n:86, love:'普通的一天，加上一束花，就不普通了。' },
