  /* ── 十一月 ── */
  '2031-11-01': { f:'玉兰', n:62, love:'窗台空了很久，今天有花了。' },
  '2031-11-02': { f:'紫罗兰', n:7, love:'今天没见到你，花替我进去了。' },
  '2031-11-03': { f:'飞燕草', n:51, love:'一页纸写不下的话，一束花装得下。' },
