  '2031-11-05': { f:'绣球', n:40, love:'花店七点关门，我六点五十到。' },
  '2031-11-06': { f:'牡丹', n:84, love:'等待也是爱的一部分，我认了。' },
  '2031-11-07': { f:'芍药', n:29, love:'这束花不贵重。贵重的是每天都记得。' },
  '2031-11-08': { f:'卡布奇诺玫瑰', n:73, love:'路很长。花撑得住，我也撑得住。' },
