  '2031-11-10': { f:'粉玫瑰', n:62, love:'花没有保质期那么长，我有。' },
  '2031-11-11': { f:'白玫瑰', n:7, love:'我把花放在你必经的地方。' },
  '2031-11-12': { f:'红玫瑰', n:51, love:'我们之间不用很多话，花就够了。' },
  '2031-11-13': { f:'黑心菊', n:94, love:'我把喜欢做得很轻，怕吓到你。' },
  '2031-11-14': { f:'虎皮百合', n:39, love:'走之前替你把花挪到阴一点的地方。' },
  '2031-11-15': { f:'台湾百合', n:83, love:'今天下雨。花在伞下，你在我心里，都没淋到。' },
  '2031-11-16': { f:'非洲菊', n:28, love:'我爱你。今天说一次，昨天也说过。' },
  '2031-11-17': { f:'向日葵', n:72, love:'一天一束，一年就是三百多束。' },
  '2031-11-18': { f:'卡布奇诺玫瑰', n:18, love:'书签是一朵压干的花，去年夹的。' },
  '2031-11-19': { f:'玉兰', n:61, love:'灯关掉之后，花还在替你亮一会儿。' },
  '2031-11-20': { f:'紫罗兰', n:6, love:'说不出为什么，就觉得今天该有花。' },
  '2031-11-21': { f:'飞燕草', n:50, love:'你笑起来的时候，花就不算什么了。' },
  '2031-11-22': { f:'木绣球', n:94, love:'别熬太晚。花都要睡了。' },
  '2031-11-23': { f:'绣球', n:39, love:'你的名字是这束花的落款。' },
  '2031-11-24': { f:'牡丹', n:83, love:'地铁很挤，只有花是站着的。' },
  '2031-11-25': { f:'芍药', n:28, love:'我把花举到窗户前，看它透光的样子，像看你笑。' },
  '2031-11-26': { f:'卡布奇诺玫瑰', n:72, love:'冬天很长，花很短。所以每天都要买。' },
  '2031-11-27': { f:'芍药', n:18, love:'四季轮着来，我轮着买。' },
  '2031-11-28': { f:'粉玫瑰', n:61, love:'你的肩膀今天有点塌，是不是累了。' },
  '2031-11-29': { f:'白玫瑰', n:6, love:'今天差点忘了。还好想起来了。' },
  '2031-11-30': { f:'红玫瑰', n:50, love:'花店里有只猫，它比你还不理人。' },

  /* ── 十二月 ── */
  '2031-12-01': { f:'黑心菊', n:93, love:'你睡着的时候，世界安静得像一束刚剪好的花。' },
  '2031-12-02': { f:'虎皮百合', n:38, love:'你说这束好看。那明天我也买这种。' },
  '2031-12-03': { f:'台湾百合', n:82, love:'黄昏最长。足够我把想你这件事做完一遍。' },
  '2031-12-04': { f:'非洲菊', n:27, love:'厨房有油烟，花在客厅躲着。' },
  '2031-12-05': { f:'向日葵', n:71, love:'手冻红了也别怕，花是暖的，我也是。' },
