  /* ── 十月 ── */
  '2033-10-01': { f:'卡布奇诺玫瑰', n:96, love:'我不保证永远，我只保证明天还有。' },
  '2033-10-02': { f:'香槟玫瑰', n:41, love:'楼下的花店老板已经认识我了。' },
  '2033-10-03': { f:'粉玫瑰', n:85, love:'我在这个城市没什么牵挂，除了你。' },
  '2033-10-04': { f:'白玫瑰', n:30, love:'你头发上有花香，是昨天那束留下的。' },
  '2033-10-05': { f:'卡布奇诺玫瑰', n:75, love:'数字不重要，重要的是每天都数。' },
  '2033-10-06': { f:'黑心菊', n:18, love:'今天下雨。花在伞下，你在我心里，都没淋到。' },
