  '2033-10-20': { f:'香槟玫瑰', n:40, love:'我不能每天都见到你，但花能。' },
  '2033-10-21': { f:'粉玫瑰', n:84, love:'我在这里，你在那里，花在中间跑腿。' },
  '2033-10-22': { f:'白玫瑰', n:29, love:'今天走了很多路，花一直在我手里。' },
  '2033-10-23': { f:'红玫瑰', n:73, love:'我买花从不讲价，怕显得不够诚心。' },
  '2033-10-24': { f:'粉玫瑰', n:18, love:'你不用担心哪天没有花。那件事不会发生。' },
  '2033-10-25': { f:'虎皮百合', n:61, love:'书翻到哪页都行，花停在今天这页。' },
  '2033-10-26': { f:'台湾百合', n:6, love:'爱你这件小事，我打算做很久。' },
  '2033-10-27': { f:'非洲菊', n:50, love:'书签是一朵压干的花，去年夹的。' },
  '2033-10-28': { f:'向日葵', n:94, love:'回家的路上买了一束花，路就不算白走。' },
