  '2033-10-30': { f:'玉兰', n:83, love:'我爱你。今天说一次，昨天也说过。' },
  '2033-10-31': { f:'紫罗兰', n:28, love:'我把花放在你必经的地方。' },

  /* ── 十一月 ── */
  '2033-11-01': { f:'飞燕草', n:72, love:'我把今天过完了，只剩想你没做。' },
