  '2034-02-13': { f:'台湾百合', n:2, love:'我把2拆开看：一支给你，其余也都给你。' },
  '2034-02-14': { f:'红玫瑰', n:99, love:'情人节一年只有一天，可爱你这件事，我打算做满三百六十五天。' },
  '2034-02-15': { f:'向日葵', n:90, love:'我想看看十年后的这束花长什么样。' },
  '2034-02-16': { f:'朱顶红', n:35, love:'等人的时候，时间会变得很具体。' },
  '2034-02-17': { f:'玉兰', n:79, love:'你的名字三个字，我念了79遍。' },
  '2034-02-18': { f:'紫罗兰', n:24, love:'等待也是爱的一部分，我认了。' },
  '2034-02-19': { f:'飞燕草', n:68, love:'愿你今天笑得比昨天多一次。' },
  '2034-02-20': { f:'木绣球', n:13, love:'我把闹钟调早了十分钟，只为多看一眼今天的花。' },
  '2034-02-21': { f:'绣球', n:57, love:'明天的花已经在路上了，你不用担心。' },
  '2034-02-22': { f:'牡丹', n:2, love:'我把花放在你必经的地方。' },
  '2034-02-23': { f:'芍药', n:46, love:'剪口要斜着剪，它才喝得进水。人也一样。' },
  '2034-02-24': { f:'卡布奇诺玫瑰', n:90, love:'今天的第一件事不是刷牙，是想你。' },
  '2034-02-25': { f:'香槟玫瑰', n:35, love:'花在窗台上等了一夜，就为了你起床时看见。' },
  '2034-02-26': { f:'粉玫瑰', n:79, love:'窗帘拉开的时候，替我看一眼花。' },
  '2034-02-27': { f:'白玫瑰', n:24, love:'桌子有点乱，只有花是正的。' },
  '2034-02-28': { f:'红玫瑰', n:68, love:'有些花只开一天。所以今天必须送。' },

  /* ── 三月 ── */
  '2034-03-01': { f:'黑心菊', n:12, love:'我没有一次是顺路买的，都是专门去的。' },
  '2034-03-02': { f:'虎皮百合', n:56, love:'花香不响，却比什么都吵。' },
  '2034-03-03': { f:'台湾百合', n:1, love:'我在这里，你在那里，花在中间跑腿。' },
  '2034-03-04': { f:'非洲菊', n:45, love:'你身上有洗衣粉的味道，比花香好闻。' },
  '2034-03-05': { f:'向日葵', n:89, love:'这束花不贵重。贵重的是每天都记得。' },
  '2034-03-06': { f:'朱顶红', n:34, love:'我准备了很多话，最后只递过去一束花。' },
  '2034-03-07': { f:'玉兰', n:78, love:'我买花从不讲价，怕显得不够诚心。' },
  '2034-03-08': { f:'紫罗兰', n:23, love:'阳光好的日子，连影子都在替我爱你。' },
  '2034-03-09': { f:'飞燕草', n:67, love:'光从花瓣上滑下来，落在我手上，像你。' },
  '2034-03-10': { f:'木绣球', n:12, love:'今天也顺利。花也顺利。' },
  '2034-03-11': { f:'绣球', n:56, love:'明年今日，我还会站在同一个花店。' },
  '2034-03-12': { f:'牡丹', n:1, love:'冬天很长，花很短。所以每天都要买。' },
  '2034-03-13': { f:'芍药', n:45, love:'这束花的位置我调了三次，还是觉得不够好。' },
  '2034-03-14': { f:'卡布奇诺玫瑰', n:89, love:'雨天路滑，你慢一点。花不急，我也不急。' },
  '2034-03-15': { f:'香槟玫瑰', n:34, love:'我把花插在空酒瓶里，也挺好看。' },
  '2034-03-16': { f:'粉玫瑰', n:78, love:'下雪了。花在屋里，你在路上，我在等。' },
  '2034-03-17': { f:'白玫瑰', n:23, love:'你说这束好看。那明天我也买这种。' },
  '2034-03-18': { f:'红玫瑰', n:67, love:'今天的花有点贵，我觉得值。' },
  '2034-03-19': { f:'黑心菊', n:11, love:'日历翻过去一页，花就少一支。' },
  '2034-03-20': { f:'虎皮百合', n:55, love:'隔着一段路，我把花先送过去。' },
  '2034-03-21': { f:'台湾百合', n:99, love:'老了也要买，只是那时候要买得慢一点。' },
  '2034-03-22': { f:'红玫瑰', n:45, love:'明年这个时候，花会更多。' },
  '2034-03-23': { f:'向日葵', n:88, love:'爱你这件小事，我打算做很久。' },
  '2034-03-24': { f:'朱顶红', n:33, love:'愿你不必解释，也不必被误解。' },
  '2034-03-25': { f:'玉兰', n:77, love:'数到77的时候我停了，再多就说不清了。' },
  '2034-03-26': { f:'紫罗兰', n:22, love:'今天不在你身边，明天补上。' },
  '2034-03-27': { f:'飞燕草', n:66, love:'灯下看花，颜色会深一点，像藏起来的心事。' },
  '2034-03-28': { f:'木绣球', n:11, love:'出门带伞。花不能带，我可以。' },
  '2034-03-29': { f:'绣球', n:55, love:'手冻红了也别怕，花是暖的，我也是。' },
  '2034-03-30': { f:'牡丹', n:99, love:'我不是不想说，是说了怕你为难。' },
  '2034-03-31': { f:'白玫瑰', n:45, love:'花不说话，但它记得被谁抱过。' },

  /* ── 四月 ── */
  '2034-04-01': { f:'卡布奇诺玫瑰', n:88, love:'泡面的三分钟，刚好够我看一眼花。' },
  '2034-04-02': { f:'香槟玫瑰', n:33, love:'今天的风很轻，刚好够把花香送到你那边。' },
  '2034-04-03': { f:'粉玫瑰', n:77, love:'楼下的花店老板已经认识我了。' },
  '2034-04-04': { f:'白玫瑰', n:22, love:'冬天的花少，所以更该送。' },
  '2034-04-05': { f:'红玫瑰', n:66, love:'愿你被这个世界善待，剩下的我来补。' },
  '2034-04-06': { f:'黑心菊', n:10, love:'你不在的时候，我把花摆在你常坐的位置。' },
  '2034-04-07': { f:'虎皮百合', n:54, love:'我把花枝剪短了两厘米，你桌上刚好放得下。' },
  '2034-04-08': { f:'台湾百合', n:98, love:'你今天回不回？花在门口站了一天。' },
  '2034-04-09': { f:'非洲菊', n:43, love:'糖放在抽屉第二格，花放在桌上第一眼。' },
  '2034-04-10': { f:'芍药', n:33, love:'又长大一岁。我不祝你万事顺遂，我只祝你年年都有人这样给你买花。' },
  '2034-04-11': { f:'朱顶红', n:32, love:'风穿过花枝的声音，像你小声叫我名字。' },
  '2034-04-12': { f:'玉兰', n:76, love:'一切照旧：上班，下班，买花，想你。' },
  '2034-04-13': { f:'紫罗兰', n:21, love:'今天下雨。花在伞下，你在我心里，都没淋到。' },
  '2034-04-14': { f:'飞燕草', n:65, love:'风把我的话吹散了，好在花还记得。' },
  '2034-04-15': { f:'木绣球', n:10, love:'我把花上的水珠擦干了，怕弄湿你的手。' },
  '2034-04-16': { f:'绣球', n:54, love:'有些话我说不出口，就让花说。' },
  '2034-04-17': { f:'牡丹', n:98, love:'门关上的声音，比什么都空。' },
  '2034-04-18': { f:'芍药', n:43, love:'你开门的时候，会先看到花，再看到我。' },
  '2034-04-19': { f:'卡布奇诺玫瑰', n:87, love:'我从不觉得这是负担，倒像每天要吃饭。' },
  '2034-04-20': { f:'香槟玫瑰', n:32, love:'我不喜欢热闹，只喜欢你在的那点安静。' },
  '2034-04-21': { f:'粉玫瑰', n:76, love:'你今天晚了半小时，花都没蔫。' },
  '2034-04-22': { f:'白玫瑰', n:21, love:'愿你今天醒来，先想起的是花，再想起是我。' },
  '2034-04-23': { f:'红玫瑰', n:65, love:'我词穷的时候，花替我开口。' },
  '2034-04-24': { f:'黑心菊', n:9, love:'我写字不好看，所以让花替我说。' },
  '2034-04-25': { f:'虎皮百合', n:53, love:'晚安不是结束，是明天还来的意思。' },
  '2034-04-26': { f:'台湾百合', n:97, love:'书翻到哪页都行，花停在今天这页。' },
  '2034-04-27': { f:'非洲菊', n:42, love:'门开着的时候，风把花香送进去了。' },
  '2034-04-28': { f:'向日葵', n:86, love:'明天见。花会先到。' },
  '2034-04-29': { f:'朱顶红', n:31, love:'你今天会来吗。花已经问过一遍了。' },
  '2034-04-30': { f:'玉兰', n:75, love:'风把窗帘吹起来的时候，花点了点头。' },

  /* ── 五月 ── */
  '2034-05-01': { f:'紫罗兰', n:20, love:'我数过，20支。多一支我怕你嫌多。' },
