  '2034-06-11': { f:'芍药', n:40, love:'很远也没关系，花是寄过去的。' },
  '2034-06-12': { f:'卡布奇诺玫瑰', n:84, love:'我一直在这儿，花也是。' },
  '2034-06-13': { f:'香槟玫瑰', n:29, love:'我想你了。这三个字今天由花来说。' },
  '2034-06-14': { f:'粉玫瑰', n:73, love:'坚持这件事，我只对花和你认真过。' },
  '2034-06-15': { f:'白玫瑰', n:18, love:'今天差点忘了。还好想起来了。' },
