  '2034-06-17': { f:'黑心菊', n:6, love:'我不擅长开口，但我擅长坚持。' },
  '2034-06-18': { f:'虎皮百合', n:50, love:'每天都买，就不会有“忘了”这种借口。' },
  '2034-06-19': { f:'台湾百合', n:94, love:'这座城有一万家店，我只进那一家。' },
  '2034-06-20': { f:'非洲菊', n:39, love:'这座城每天都不一样，我只做同一件事。' },
  '2034-06-21': { f:'向日葵', n:83, love:'我不擅长表达，所以一天一束，积少成多。' },
