  '2034-06-24': { f:'红玫瑰', n:18, love:'城市很吵，花很安静。' },
  '2034-06-25': { f:'飞燕草', n:61, love:'以后每天都有，你就习惯了。' },
  '2034-06-26': { f:'木绣球', n:6, love:'你眼睛里有光，跟花没关系。' },
