  '2034-06-28': { f:'牡丹', n:94, love:'今天的花是老板推荐的，他说适合送人。' },
  '2034-06-29': { f:'芍药', n:39, love:'夜里回家，看到窗口有花，就像看到你。' },
  '2034-06-30': { f:'卡布奇诺玫瑰', n:83, love:'我把花放在门口，按了铃就走。' },

  /* ── 七月 ── */
  '2034-07-01': { f:'香槟玫瑰', n:28, love:'今天的天气配这束花，刚刚好。' },
  '2034-07-02': { f:'粉玫瑰', n:72, love:'别熬太晚。花都要睡了。' },
