  '2034-07-04': { f:'红玫瑰', n:61, love:'我今天没什么事，就是把花摆了三遍。' },
  '2034-07-05': { f:'黑心菊', n:5, love:'这件事我做了很多天，还会做很多天。' },
  '2034-07-06': { f:'虎皮百合', n:49, love:'一年里最普通的一天，也值得被记住。' },
  '2034-07-07': { f:'台湾百合', n:93, love:'你的杯子旁边有空位，我放了花。' },
  '2034-07-08': { f:'非洲菊', n:38, love:'春天的花最吵，夏天的最甜。' },
  '2034-07-09': { f:'向日葵', n:82, love:'清晨的光落在花瓣上，我落在想你这件事上。' },
  '2034-07-10': { f:'朱顶红', n:27, love:'下午三点的光最好，刚好照在你常坐的位置。' },
  '2034-07-11': { f:'玉兰', n:71, love:'想你的时候我就去买花，久了就成了习惯。' },
  '2034-07-12': { f:'紫罗兰', n:16, love:'我把话都放轻了，怕吵醒这束花。' },
  '2034-07-13': { f:'飞燕草', n:60, love:'我离你有点远，花离你很近。' },
  '2034-07-14': { f:'木绣球', n:5, love:'今天没什么特别的，就是有花。' },
