  '2035-05-28': { f:'白玫瑰', n:15, love:'花不说话，但它记得被谁抱过。' },
  '2035-05-29': { f:'白玫瑰', n:58, love:'明天见。花会先到。' },
  '2035-05-30': { f:'红玫瑰', n:3, love:'你今天有没有一刻，也想起我。' },
  '2035-05-31': { f:'黑心菊', n:46, love:'将来搬家，第一件事是找一个能放花的窗台。' },

  /* ── 六月 ── */
  '2035-06-01': { f:'虎皮百合', n:90, love:'坚持这件事，我只对花和你认真过。' },
  '2035-06-02': { f:'台湾百合', n:35, love:'路很长。花撑得住，我也撑得住。' },
  '2035-06-03': { f:'非洲菊', n:79, love:'不吵不闹，就这样一天一束。' },
  '2035-06-04': { f:'向日葵', n:24, love:'你在那边，我在这边，花在中间。' },
  '2035-06-05': { f:'朱顶红', n:68, love:'窗外是车流，窗内是一束花。' },
  '2035-06-06': { f:'玉兰', n:13, love:'今天我们离得有点远。花替我先到。' },
  '2035-06-07': { f:'紫罗兰', n:57, love:'我把花放在你必经的地方。' },
  '2035-06-08': { f:'飞燕草', n:2, love:'今天的花是老板推荐的，他说适合送人。' },
  '2035-06-09': { f:'木绣球', n:46, love:'我数过，46支。多一支我怕你嫌多。' },
  '2035-06-10': { f:'绣球', n:90, love:'我不能每天都见到你，但花能。' },
  '2035-06-11': { f:'牡丹', n:35, love:'早上好。花先到，我才敢说这句话。' },
  '2035-06-12': { f:'芍药', n:79, love:'喜欢是藏不住的，所以我干脆每天送。' },
  '2035-06-13': { f:'卡布奇诺玫瑰', n:24, love:'你的杯子旁边有空位，我放了花。' },
  '2035-06-14': { f:'香槟玫瑰', n:68, love:'你醒来的那一刻，这束花就白等了半宿——它想第一个看见你。' },
  '2035-06-15': { f:'粉玫瑰', n:13, love:'我打算买到我们都不好意思为止。' },
  '2035-06-16': { f:'白玫瑰', n:57, love:'愿你不必解释，也不必被误解。' },
  '2035-06-17': { f:'红玫瑰', n:2, love:'你今天读了什么？我读了一束花。' },
  '2035-06-18': { f:'黑心菊', n:45, love:'你的名字是这束花的落款。' },
  '2035-06-19': { f:'虎皮百合', n:89, love:'我在这个城市没什么牵挂，除了你。' },
  '2035-06-20': { f:'台湾百合', n:34, love:'记得喝水。花每天都喝，你也一样。' },
  '2035-06-21': { f:'非洲菊', n:78, love:'花在瓶里等，我在门口等，你总会来。' },
  '2035-06-22': { f:'向日葵', n:23, love:'你要是问我为什么送花，我说不上来。' },
  '2035-06-23': { f:'朱顶红', n:67, love:'我把喜欢你藏在花里，你找找看。' },
  '2035-06-24': { f:'玉兰', n:12, love:'糖放在抽屉第二格，花放在桌上第一眼。' },
  '2035-06-25': { f:'紫罗兰', n:56, love:'你的肩膀今天有点塌，是不是累了。' },
  '2035-06-26': { f:'飞燕草', n:1, love:'路过便利店，顺手买了瓶新的水给花。' },
  '2035-06-27': { f:'木绣球', n:45, love:'你包里放颗糖。花不能吃，糖能。' },
  '2035-06-28': { f:'绣球', n:89, love:'说不出为什么，就觉得今天该有花。' },
  '2035-06-29': { f:'牡丹', n:34, love:'这束花没有附信。想说的都在里面了。' },
  '2035-06-30': { f:'芍药', n:78, love:'起风了。我想起你，也想起该收衣服了。' },

  /* ── 七月 ── */
  '2035-07-01': { f:'卡布奇诺玫瑰', n:23, love:'雪落在窗台上，花落在光里，我落在想你里。' },
  '2035-07-02': { f:'香槟玫瑰', n:67, love:'今天的风很轻，刚好够把花香送到你那边。' },
  '2035-07-03': { f:'粉玫瑰', n:12, love:'我等过很多次，都等到了。' },
  '2035-07-04': { f:'白玫瑰', n:56, love:'数字不重要，重要的是每天都数。' },
  '2035-07-05': { f:'红玫瑰', n:1, love:'灯下看花，颜色会深一点，像藏起来的心事。' },
  '2035-07-06': { f:'红玫瑰', n:45, love:'你眼睛里有光，跟花没关系。' },
  '2035-07-07': { f:'虎皮百合', n:88, love:'我煮了面，多打了一个蛋，像多买一支花。' },
  '2035-07-08': { f:'台湾百合', n:33, love:'今天也顺利。花也顺利。' },
  '2035-07-09': { f:'非洲菊', n:77, love:'愿你今天被温柔对待。' },
  '2035-07-10': { f:'向日葵', n:22, love:'你收到的每一束，都是当天的。' },
  '2035-07-11': { f:'朱顶红', n:66, love:'你翻身的动静，比任何声音都让我安心。' },
  '2035-07-12': { f:'玉兰', n:11, love:'你回家开门的那一下，花会先亮起来。' },
  '2035-07-13': { f:'紫罗兰', n:55, love:'安静地爱你，是我最擅长的事。' },
  '2035-07-14': { f:'飞燕草', n:99, love:'你开门的时候，会先看到花，再看到我。' },
  '2035-07-15': { f:'白玫瑰', n:45, love:'愿你今天不必逞强。' },
  '2035-07-16': { f:'绣球', n:88, love:'灯亮起来的那一刻，房间才算有了花。' },
  '2035-07-17': { f:'牡丹', n:33, love:'沉默有时候也是回答，花就是。' },
  '2035-07-18': { f:'芍药', n:77, love:'我起得比花早，就为了把花摆正一点。' },
  '2035-07-19': { f:'卡布奇诺玫瑰', n:22, love:'今天光很好。我想和你一起浪费掉。' },
  '2035-07-20': { f:'香槟玫瑰', n:66, love:'我数学不好，但66我还是数得清的。' },
  '2035-07-21': { f:'粉玫瑰', n:11, love:'雨停之后会有味道，那是我想让你闻到的。' },
  '2035-07-22': { f:'白玫瑰', n:55, love:'我叫你的时候，语气会不自觉轻一点。' },
  '2035-07-23': { f:'白玫瑰', n:99, love:'我把花放在光里，让它先替你晒一会儿。' },
  '2035-07-24': { f:'黑心菊', n:43, love:'花会谢，这件事不会。' },
  '2035-07-25': { f:'虎皮百合', n:87, love:'我不懂浪漫，我只是每天做同一件小事。' },
  '2035-07-26': { f:'台湾百合', n:32, love:'剪口要斜着剪，它才喝得进水。人也一样。' },
  '2035-07-27': { f:'非洲菊', n:76, love:'我从不觉得这是负担，倒像每天要吃饭。' },
  '2035-07-28': { f:'向日葵', n:21, love:'你说家里快放不下了。那就换个大点的屋子。' },
  '2035-07-29': { f:'朱顶红', n:65, love:'门关上的声音，比什么都空。' },
  '2035-07-30': { f:'玉兰', n:10, love:'四季轮着来，我轮着买。' },
  '2035-07-31': { f:'紫罗兰', n:54, love:'这座城有一万家店，我只进那一家。' },

  /* ── 八月 ── */
  '2035-08-01': { f:'飞燕草', n:98, love:'我把花放在桌上，然后开始想你。' },
