  '2035-08-31': { f:'台湾百合', n:30, love:'等人的时候，时间会变得很具体。' },

  /* ── 九月 ── */
  '2035-09-01': { f:'粉玫瑰', n:75, love:'我买花从不讲价，怕显得不够诚心。' },
