  '2035-09-03': { f:'朱顶红', n:63, love:'夏天太热，花蔫得快，我每天换水。' },
  '2035-09-04': { f:'玉兰', n:8, love:'一年之后，这束花会变成很多束。' },
  '2035-09-05': { f:'紫罗兰', n:52, love:'你嫌麻烦的话，我可以不送。但我不会。' },
  '2035-09-06': { f:'飞燕草', n:96, love:'今天不在你身边，明天补上。' },
  '2035-09-07': { f:'木绣球', n:41, love:'我不保证永远，我只保证明天还有。' },
  '2035-09-08': { f:'绣球', n:85, love:'今天的花配今天的茶，明天换一种。' },
  '2035-09-09': { f:'牡丹', n:30, love:'你下班走哪条路？我把花放在那儿了。' },
  '2035-09-10': { f:'卡布奇诺玫瑰', n:75, love:'每天都不一样，只有这件事一样。' },
  '2035-09-11': { f:'卡布奇诺玫瑰', n:19, love:'今天这束是第几束我不知道，反正不是最后一束。' },
  '2035-09-12': { f:'香槟玫瑰', n:63, love:'花在瓶里站直了，像在等我夸它。' },
  '2035-09-13': { f:'粉玫瑰', n:8, love:'日子过得很快，花换得很慢。' },
  '2035-09-14': { f:'白玫瑰', n:52, love:'冬天很长，花很短。所以每天都要买。' },
  '2035-09-15': { f:'红玫瑰', n:96, love:'花店老板问我今天送谁，我说还是那个人。' },
  '2035-09-16': { f:'黑心菊', n:40, love:'你把它插在哪了？我想知道。' },
  '2035-09-17': { f:'虎皮百合', n:84, love:'雨天路滑，你慢一点。花不急，我也不急。' },
  '2035-09-18': { f:'台湾百合', n:29, love:'我把买花写进了日程，排在所有事前面。' },
