  '2035-09-20': { f:'向日葵', n:18, love:'晚安不是结束，是明天还来的意思。' },
  '2035-09-21': { f:'朱顶红', n:62, love:'你还没醒，花已经替我说过一遍早安了。' },
  '2035-09-22': { f:'玉兰', n:7, love:'你笑起来的时候，花就不算什么了。' },
  '2035-09-23': { f:'紫罗兰', n:51, love:'愿你今天笑得比昨天多一次。' },
  '2035-09-24': { f:'飞燕草', n:95, love:'字会写错，花不会。' },
  '2035-09-25': { f:'木绣球', n:40, love:'下午三点的光最好，刚好照在你常坐的位置。' },
  '2035-09-26': { f:'绣球', n:84, love:'我把花上的水珠擦干了，怕弄湿你的手。' },
  '2035-09-27': { f:'牡丹', n:29, love:'我不是不想说，是说了怕你为难。' },
  '2035-09-28': { f:'芍药', n:73, love:'我一进门先看花，再看有没有你的鞋。' },
  '2035-09-29': { f:'卡布奇诺玫瑰', n:18, love:'我把话都放轻了，怕吵醒这束花。' },
  '2035-09-30': { f:'香槟玫瑰', n:62, love:'愿你晚上睡个好觉，梦里没有工作。' },

  /* ── 十月 ── */
  '2035-10-01': { f:'粉玫瑰', n:7, love:'今天没见到你，花替我进去了。' },
  '2035-10-02': { f:'白玫瑰', n:51, love:'你身上有洗衣粉的味道，比花香好闻。' },
  '2035-10-03': { f:'红玫瑰', n:95, love:'你的名字我写在花束的卡片背面了。' },
  '2035-10-04': { f:'黑心菊', n:39, love:'今天没下雨，花一路都很好。' },
  '2035-10-05': { f:'虎皮百合', n:83, love:'累的话就先坐一会儿，花不急。' },
  '2035-10-06': { f:'台湾百合', n:28, love:'手冻红了也别怕，花是暖的，我也是。' },
  '2035-10-07': { f:'非洲菊', n:72, love:'等待也是爱的一部分，我认了。' },
  '2035-10-08': { f:'香槟玫瑰', n:18, love:'笨办法：每天买一束，买到你信为止。' },
  '2035-10-09': { f:'朱顶红', n:61, love:'我用铅笔在日历上画了个圈，就是今天。' },
  '2035-10-10': { f:'玉兰', n:6, love:'我把闹钟调早了十分钟，只为多看一眼今天的花。' },
  '2035-10-11': { f:'紫罗兰', n:50, love:'我把花靠在门边，它站得很直。' },
  '2035-10-12': { f:'飞燕草', n:94, love:'你戴围巾的样子，比花耐看。' },
  '2035-10-13': { f:'木绣球', n:39, love:'花瓣掉了一片在桌上，我没扫。' },
  '2035-10-14': { f:'绣球', n:83, love:'我词穷的时候，花替我开口。' },
  '2035-10-15': { f:'牡丹', n:28, love:'我说不出想你，就说今天有花。' },
  '2035-10-16': { f:'芍药', n:72, love:'一年三百六十五天，我只记得有你的那些。' },
